function markdownRules(ctx){const R=ctx.pmRules.InputRule;const mark=(pattern,name,attrs)=>new R(pattern,(s,m,start,end)=>{const type=s.schema.marks[name],text=m[1],tr=s.tr.insertText(text,start,end).addMark(start,start+text.length,type.create(attrs?attrs(m):undefined)).removeStoredMark(type);return tr.setSelection(ctx.pmState.TextSelection.create(tr.doc,start+text.length)).setStoredMarks([]);});return {wysiwygPlugins:[()=>new ctx.pmState.Plugin({view(view){const entry=instances.get(activeEditorId);if(entry)entry.view=view;return {};}}),()=>ctx.pmRules.inputRules({rules:[new R(/^(#{1,2})\s$/,(s,m,start,end)=>s.tr.delete(start,end).setBlockType(start,start,s.schema.nodes.heading,{level:m[1].length})),new R(/^>\s$/,(s,m,start,end)=>{const tr=s.tr.delete(start,end),range=tr.doc.resolve(start).blockRange();return tr.wrap(range,[{type:s.schema.nodes.blockQuote}]);}),new R(/^[-*]\s$/,(s,m,start,end)=>{const tr=s.tr.delete(start,end),range=tr.doc.resolve(start).blockRange();return tr.wrap(range,[{type:s.schema.nodes.bulletList},{type:s.schema.nodes.listItem}]);}),mark(/\*\*([^*]+)\*\*$/,'strong'),mark(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)$/,'link',m=>({linkUrl:m[2]}))]}),()=>ctx.pmKeymap.keymap({Backspace:ctx.pmRules.undoInputRule})]};}
